#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# cut-release.sh: build release/vX.Y.Z, the branch a release PR merges into
# main (api/docs/rfcs/RFC-037 §4.2, §4.3).
#
#   cut-release.sh --version vX.Y.Z --sha SHA [--push]                 (train)
#   cut-release.sh --version vX.Y.Z --mode hotfix --picks "SHA ..." [--push]
#
#   --remote NAME   default origin;  --main BRANCH  default main
#   --repo DIR      the clone to work in (default .)
#
# Both modes add one version commit: it writes api/deploy/VERSION = VERSION,
# the file setup.sh reads, so the tag's checkout installs its own version. It
# is the only version in the tree and exists on the release branch and main
# only: develop never receives it (post-release.sh merges main back with
# `-s ours`) and carries no version of its own. The API and web report the
# version they are built with (ldflags from the tag).
#
# Train: the branch is SHA (a develop commit), the version commit, then one
# `merge -s ours` commit that records main as a parent. Its tree is SHA's tree
# plus the version commit, and it merges into main cleanly whatever merge
# button is used: main's squashed release commits are no longer conflicts.
# The head stays the two-parent merge (Release Publish reads "train" from it).
# (api/scripts/release-branch.sh is the older, interactive form without the
# version commit.)
#
# `-s ours` discards main's side, so it is only honest when develop already has
# everything main has. Checked per file: a file on main that is missing at SHA
# is fine when develop deleted it (a deliberate removal ships with the
# release); a file develop never had is a fix made on main alone, and the cut
# is refused rather than silently dropping it. api/deploy/VERSION is the one
# file main has and develop never does, by design; the version commit replaces it.
#
# Hotfix: the branch is the last release tag plus the picked commits,
# cherry-picked with -x in the order given, then the version commit.
#
# Prints KEY=VALUE lines: BRANCH, HEAD, BASE.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib.sh
source "$HERE/lib.sh"

VERSION=""
SHA=""
MODE="train"
PICKS=""
PUSH=0
REMOTE="origin"
MAIN="main"
REPO="."
while [[ $# -gt 0 ]]; do
  case "$1" in
    --version) VERSION="$2"; shift ;;
    --sha) SHA="$2"; shift ;;
    --mode) MODE="$2"; shift ;;
    --picks) PICKS="$2"; shift ;;
    --push) PUSH=1 ;;
    --remote) REMOTE="$2"; shift ;;
    --main) MAIN="$2"; shift ;;
    --repo) REPO="$2"; shift ;;
    -h|--help) awk 'NR > 1 && /^#/ { sub(/^# ?/, ""); if ($0 !~ /^shellcheck/) print; next } NR > 1 { exit }' "$0"; exit 0 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
  shift
done

die() { echo "REFUSING: $*" >&2; exit 1; }
g() { git -C "$REPO" "$@"; }

rel_is_version "$VERSION" || { echo "--version must be vX.Y.Z, got '$VERSION'" >&2; exit 2; }
[[ "$MODE" == train || "$MODE" == hotfix ]] || { echo "--mode must be train or hotfix" >&2; exit 2; }
BRANCH="release/$VERSION"

g fetch --quiet --tags "$REMOTE" "+refs/heads/*:refs/remotes/$REMOTE/*"
main_ref="refs/remotes/$REMOTE/$MAIN"
g rev-parse -q --verify "$main_ref" >/dev/null || die "$REMOTE/$MAIN does not exist"

last="$(rel_latest_tag "$REPO")"
if [[ -n "$last" ]] && ! rel_version_gt "$VERSION" "$last"; then
  die "$VERSION is not greater than the last release $last"
fi
g rev-parse -q --verify "refs/tags/$VERSION" >/dev/null && die "tag $VERSION already exists"
if g ls-remote --exit-code --heads "$REMOTE" "$BRANCH" >/dev/null 2>&1; then
  die "$REMOTE/$BRANCH already exists; delete it or pick another version (this script never force-pushes)"
fi

worktree="$(mktemp -d)"
cleanup() {
  g worktree remove --force "$worktree" >/dev/null 2>&1 || true
  rm -rf "$worktree" "${tagscripts:-}"
}
tagscripts=""
trap cleanup EXIT

# refuse_cut MESSAGE: drop the half-built local branch, then refuse.
refuse_cut() {
  cleanup
  g branch -D "$BRANCH" >/dev/null 2>&1 || true
  die "$*"
}

# The version checks run with the scripts of the tree being released. A
# hotfix is the old tag's tree, whose versions.yaml layout the current
# scripts may not know: use the tag's own copy (a train uses these scripts).
checker="$HERE/sync-versions.sh"

# version_commit: commit api/deploy/VERSION = VERSION on the worktree's branch.
version_commit() {
  mkdir -p "$worktree/$(dirname "$VERSION_FILE")"
  printf '%s\n' "$VERSION" >"$worktree/$VERSION_FILE"
  bash "$checker" --root "$worktree" --release "$VERSION" >&2 ||
    refuse_cut "the tree does not pass the version checks on the release branch"
  git -C "$worktree" add -- "$VERSION_FILE"
  if ! git -C "$worktree" diff --cached --quiet; then
    git -C "$worktree" commit --quiet -m "chore(release): $VERSION_FILE = $VERSION

The tag's checkout installs its own version. Generated by
.github/scripts/release/cut-release.sh."
  fi
}

if [[ "$MODE" == train ]]; then
  [[ -n "$SHA" ]] || { echo "--sha is required for a train" >&2; exit 2; }
  SHA="$(g rev-parse --verify "$SHA^{commit}")"

  refused=()
  kept_deleted=()
  # -m: a deletion made in a merge commit counts (plain log shows no diff for merges).
  while IFS= read -r path; do
    [[ -n "$path" ]] || continue
    [[ "$path" != "$VERSION_FILE" ]] || continue
    if [[ -n "$(g log -m -1 --format=%H --diff-filter=D "$SHA" -- "$path")" ]]; then
      kept_deleted+=("$path")
    else
      refused+=("$path")
    fi
  done < <(g diff --no-renames --name-only --diff-filter=A "$SHA" "$main_ref")
  if [[ ${#refused[@]} -gt 0 ]]; then
    {
      echo "REFUSING: ${#refused[@]} file(s) exist on $MAIN but were never on develop:"
      printf '  %s\n' "${refused[@]}"
      echo "-s ours would silently drop them. Bring them to develop first (merge or cherry-pick)."
    } >&2
    exit 1
  fi
  for path in "${kept_deleted[@]}"; do
    echo "note: $path is on $MAIN, deleted on develop; the release removes it" >&2
  done

  g branch -f "$BRANCH" "$SHA" >/dev/null
  g worktree add --quiet "$worktree" "$BRANCH"
  version_commit
  bumped_tree="$(git -C "$worktree" rev-parse 'HEAD^{tree}')"
  git -C "$worktree" merge -s ours --no-edit "$main_ref" -m "chore(release): carry $MAIN's ancestry into $VERSION

-s ours keeps develop's tree (${SHA:0:12}) plus the version commit byte for
byte and only records $MAIN as a parent, so the release PR merges without
false conflicts. Generated by .github/scripts/release/cut-release.sh." >/dev/null

  [[ "$(git -C "$worktree" rev-parse 'HEAD^{tree}')" == "$bumped_tree" ]] ||
    die "the release branch's tree differs from $SHA's plus the version commit"
  git -C "$worktree" merge-base --is-ancestor "$main_ref" HEAD || die "$MAIN is not an ancestor after the merge"
  BASE="$SHA"
else
  [[ -n "${PICKS// /}" ]] || { echo "--picks is required for a hotfix" >&2; exit 2; }
  [[ -n "$last" ]] || die "a hotfix needs a previous release tag"
  [[ "$VERSION" == "$(rel_next_version "$last" patch)" ]] ||
    die "a hotfix of $last is $(rel_next_version "$last" patch), not $VERSION"
  g merge-base --is-ancestor "$last" "$main_ref" || die "$last is not on $MAIN"
  [[ "$(g rev-parse "$last^{tree}")" == "$(g rev-parse "$main_ref^{tree}")" ]] ||
    die "$MAIN has changed since $last; a hotfix is built on the released tree only"

  g branch -f "$BRANCH" "$last^{commit}" >/dev/null
  g worktree add --quiet "$worktree" "$BRANCH"
  for p in $PICKS; do
    # The queue merges with MERGE commits, so a PR's merge commit is what
    # people pass: pick its first-parent diff (-m 1).
    mflag=()
    if [[ "$(git -C "$worktree" rev-list --parents -n 1 "$p" | wc -w)" -gt 2 ]]; then mflag=(-m 1); fi
    if ! git -C "$worktree" cherry-pick -x ${mflag[@]+"${mflag[@]}"} "$p" >/dev/null 2>&1; then
      git -C "$worktree" cherry-pick --abort >/dev/null 2>&1 || true
      refuse_cut "cherry-pick of $p onto $last conflicts; backport it by hand"
    fi
  done
  tagscripts="$(mktemp -d)"
  if g archive "$last" .github/scripts/release 2>/dev/null | tar -x -C "$tagscripts" 2>/dev/null &&
    [[ -f "$tagscripts/.github/scripts/release/sync-versions.sh" ]]; then
    checker="$tagscripts/.github/scripts/release/sync-versions.sh"
  fi
  version_commit
  BASE="$(g rev-parse "$last^{commit}")"
fi

HEAD_SHA="$(git -C "$worktree" rev-parse HEAD)"
if [[ $PUSH -eq 1 ]]; then
  git -C "$worktree" push --quiet "$REMOTE" "HEAD:refs/heads/$BRANCH"
  echo "pushed $BRANCH" >&2
fi
cat <<EOF
BRANCH=$BRANCH
HEAD=$HEAD_SHA
BASE=$BASE
EOF
